public sealed class Account
{
    private readonly decimal floor;
    private decimal balance;

    public Account(decimal floor)
    {
        if (floor < 0) throw new ArgumentOutOfRangeException(nameof(floor));
        this.floor = floor;
        balance = floor;
        Debug.Assert(balance >= this.floor, "invariant: balance below floor");
    }

    public void Withdraw(decimal amount)
    {
        if (amount <= 0) throw new ArgumentOutOfRangeException(nameof(amount));
        var nextBalance = balance - amount;
        if (nextBalance < floor) throw new InvalidOperationException("insufficient balance");
        balance = nextBalance;
        Debug.Assert(balance >= floor, "invariant: balance below floor");
    }
}
